 async function startSession(){if(!selected||!savedAttendanceReady||!beforePhotoCaptured)return;setBusy(true);setError("");try{await trainingSessionAction({sessionId:selected.id,action:"start"});await refresh(providerId,selected.id);notify("Session start recorded");}catch(problem){setError(problem instanceof Error?problem.message:"Training session update failed");}finally{setBusy(false);}}
 async function refreshEvidence(){if(!selected||busy)return;setBusy(true);try{await showEvidence(selected.id);}finally{setBusy(false);}}
 async function addEvidence(file:File,purpose:TrainingEvidencePurpose){if(!selected||busy)return;if(purpose==="training_video"&&!trainingVideoValidation(file)){setError("Choose an MP4 or WebM training video no larger than 10 MB.");return;}setBusy(true);setError("");const current=newestRequest(evidenceRequest);try{const uploaded=await prepareTrainingEvidence({sessionId:selected.id,file,purpose});const result=await loadTrainingEvidence(selected.id);if(current()){setEvidence(result.assets);setEvidenceSessionId(selected.id);setEvidenceError("");}notify(uploaded.alreadyUploaded?"This evidence is already registered. Its current approval status is shown below.":uploaded.objectStored?"Evidence uploaded. Waiting for scan and independent approval.":"Evidence bytes received in sandbox; private storage is not connected. Completion still requires approved proof.");}catch(problem){setError(problem instanceof Error?problem.message:"Unable to upload Training evidence");try{const result=await loadTrainingEvidence(selected.id);if(current())setEvidence(result.assets);}catch{if(current())setEvidenceError("Unable to reload photos. Retry the approval refresh.");}}finally{setBusy(false);}}
 if(loading)return <main className={styles.shell}><section className={styles.main}><h1>Loading trainer workspace…</h1></section></main>;
 if(!providerId)return <main className={styles.shell}><section className={styles.main}><h1>Trainer sign-in required</h1><p>{error||"Verify the trainer identity with the PawSpace provider OTP session before opening assigned sessions."}</p><Link href={partnerHref}>Return to Partner</Link></section></main>;
 const nowLabel=new Intl.DateTimeFormat("en-IN",{weekday:"long",day:"numeric",month:"long"}).format(new Date());
 return <main className={styles.shell}>
  <aside><div className={styles.brand}><span>paw●space</span><small>TRAINER PARTNER</small></div><div className={styles.trainer}><span>TR</span><div><strong>{trainerName||providerId}</strong><small>Authenticated provider session</small></div></div><nav><button className={tab==="today"?styles.active:""} onClick={()=>void openTab("today")}>▦ Sessions</button><button className={tab==="clients"?styles.active:""} onClick={()=>void openTab("clients")}>🐾 Programmes</button><button className={tab==="earnings"?styles.active:""} onClick={()=>void openTab("earnings")}>₹ Earnings</button></nav><div className={styles.links}><Link href={partnerHref}>Partner home</Link><Link href={trainingHref}>Customer training</Link></div></aside>
  <section className={styles.main}><header><div><p>{nowLabel}</p><h1>{tab==="today"?"Your canonical training sessions":tab==="clients"?"Dogs & programmes":"Training earnings readiness"}</h1></div><span><i></i>{sessions.length} assigned session{sessions.length===1?"":"s"}</span></header>
