    {selected&&<article className={styles.session}><div className={styles.sessionHead}><div><span>{selected.id} · Booking {selected.booking_id}</span><h2>{selected.plan_name}</h2><p>{selected.customer_name} · Session {selected.sequence_no} of {selected.total_sessions}</p></div><b>{statusLabel(selected.status)}</b></div>{currentContext?.arrival.evidence?.simulated&&<p role="status">Sandbox arrival simulation — not a physical visit.</p>}{currentContext?.navigation.available&&currentContext.navigation.mapsUrl&&<p><a href={currentContext.navigation.mapsUrl} target="_blank" rel="noopener noreferrer">Navigate to customer doorstep</a></p>}{contextError&&<p role="alert">{contextError}</p>}{currentContext&&!currentContext.navigation.available&&currentContext.navigation.reason&&<p>{currentContext.navigation.reason==="address_window_closed"?"Customer navigation becomes available within the approved address-access window before the session.":"Customer navigation is unavailable. Contact Operations if you need help reaching this session."}</p>}<div className={styles.actions}>{selected.providerModel!=="full_time"&&<button disabled={busy||selected.status!=="scheduled"} onClick={()=>void act("accept")}>Accept</button>}<button disabled={busy||!(selected.status==="accepted"||selected.providerModel==="full_time"&&selected.status==="scheduled")} onClick={()=>void act("on_the_way")}>On the way</button><button disabled={busy||selected.status!=="on_the_way"} onClick={()=>void act("arrive")}>Confirm arrival with device GPS</button></div>{selected.status==="on_the_way"&&currentContext?.arrival.simulation.eligible&&currentContext.arrival.simulation.approvalId&&<section className={styles.precheck}><p>{currentContext.arrival.simulation.label}. This records a test simulation, not a physical visit.</p><button disabled={busy} onClick={()=>{const reason=window.prompt("Explain this approved sandbox arrival simulation (at least 8 characters)")?.trim();if(reason&&reason.length>=8)void act("arrive",{simulatedArrival:{approvalId:currentContext.arrival.simulation.approvalId,reason}});}}>Simulate approved sandbox arrival</button></section>}
     {["scheduled","accepted","on_the_way","arrived"].includes(selected.status)&&<section className={styles.precheck}><span>RECOVERY</span><p>Reschedule requests and no-show records open an auditable recovery case; they do not silently consume a paid session.</p><button disabled={busy} onClick={()=>{const reason=window.prompt("Why must this session be rescheduled?")||"";if(reason)void act("request_reschedule",{reason});}}>Request reschedule</button><button disabled={busy} onClick={()=>{const reason=window.prompt("Record the no-show reason")||"";if(reason)void act("no_show",{reason});}}>Record no-show</button></section>}
     {selected.status==="arrived"&&<section className={styles.precheck}><span>SESSION PRE-CHECK</span><p>Save attendance and safe-area confirmation, then capture the before photo before starting.</p>{attendanceControls}<button disabled={busy||!evidenceSettled||!attendanceReady} onClick={()=>void act("save_report",{report:{attendance:report.attendance}})}>Save attendance &amp; safety</button><button disabled={busy||!savedAttendanceReady||!beforePhotoCaptured} onClick={()=>void startSession()}>Start session</button></section>}
