s safe. This is saved with the report and is required to complete the session.</p>{attendanceControls}</section><div className={styles.actions}><button disabled={busy||!evidenceSettled} onClick={()=>void act("save_report",{report})}>Save report</button><button className={styles.complete} disabled={busy||!evidenceSettled||Boolean(evidenceError)||homework.trim().length<10||!hasBothPhotos||!selected.ownerHandover||!attendanceReady||!trainingProgressReady(scores)} onClick={()=>void act("complete",{report})}>Complete & consume one session</button></div></>}
     {(selected as TrainerSession&{schedulingMode?:string}).schedulingMode==="rolling_v1"&&<TrainerRollingSchedule key={selected.id} bookingId={selected.booking_id} sessionId={selected.id} providerId={providerId} onChanged={()=>refresh(providerId,selected.id)}/>}
     {selected.status==="completed"&&<section className={styles.success}><i>✓</i><h2>Session completed canonically</h2><p>Exactly one session consumption is recorded. Attendance, scores, homework and secure evidence remain attached to this session.</p></section>}
