   {tab==="earnings"&&<EarningsLoadState loading={earningsLoading} error={earningsError} loaded={earnings!==null} onRetry={()=>void loadEarnings()}><section className={styles.earnings}><div className={styles.hero}><span>CANONICAL TRAINING PAYOUT LEDGER</span><strong>{earnings?money(earnedAmount):busy?"Loading…":"No earnings ledger yet"}</strong><p>{earnings?`Execution: ${earnings.executionMode.replaceAll("_"," ")}. Finance approval is required for payout. Live payout is not connected.`:"Only completed canonical sessions can enter this ledger. A Finance-published rate is required before money is shown as earned."}</p></div><div className={styles.stats}><article><span>Completed session earnings</span><strong>{earnings?.earnings.filter(item=>item.status==="earned").length??0}</strong><small>Rate configured + customer payment captured</small></article><article><span>Pending rate / holds</span><strong>{earnings?.earnings.filter(item=>item.status!=="earned").length??0}</strong><small>No invented amount while blocked</small></article><article><span>Payout statement</span><strong>{earnings?.payouts[0]?.status.replaceAll("_"," ")||"Not created"}</strong><small>{earnings?.payouts[0]?`${earnings.payouts[0].period_code} · ${money(earnings.payouts[0].earned_amount)}`:"Appears after completed-session earnings exist"}</small></article></div>{earnings?.earnings.length?<section className={styles.clientGrid}>{earnings.earnings.map(item=><article key={item.session_id}><span>₹</span><h2>{item.gross_earning===null?"Rate pending":money(item.gross_earning)}</h2><p>{item.session_id} · {item.package_code}</p><div><strong>{item.status.replaceAll("_"," ")}</strong><small>{item.hold_reason||"Eligible completed session"}</small></div></article>)}</section>:null}</section></EarningsLoadState>}
  </section>{toast&&<div className={styles.toast}>✓ {toast}</div>}
 </main>;
