"use client";

import TrainingBroadcastInbox from "./training-broadcast-inbox";
import {trainingAttendanceReady,trainingBeforeCaptured} from "../../lib/training-partner-precheck";
import Link from"next/link";
import TrainerRollingSchedule from "./rolling-schedule";
import {trainingVideoValidation,trainingHandoverReminder,trainingHomeworkStatus} from "./lifecycle-presentation";
import {formatIndiaDateTimeMedium} from "../../lib/india-time";
import EarningsLoadState from "./earnings-load-state";
import {TrainingEvidenceControls,TrainingOwnerHandover,TrainingVideoControls} from "./session-proof";
import{Suspense,useEffect,useMemo,useRef,useState}from"react";
import {usePathname,useSearchParams} from "next/navigation";
import baseStyles from"./trainer.module.css";
import extraStyles from"./trainer-extra.module.css";
import{currentProviderIdentity,loadTrainerSessions,loadTrainingEvidence,prepareTrainingEvidence,trainingSessionAction,type TrainerSession,type TrainingEvidenceAsset,type TrainingEvidencePurpose}from"../../lib/training-session-client";
import{trainingProgressFromRecord,trainingProgressReady,type TrainingProgressScores}from"../../lib/training-progress-editor";
const styles={...baseStyles,...extraStyles};
type SessionContext={sessionId:string;navigation:{available:boolean;mapsUrl:string|null;reason:string|null};handover:{completed:boolean;completedAt:number|null;remindAt:number|null;reminderDue:boolean};arrival:{thresholdMeters:number;evidence?:{mode:string;simulated:boolean;physicalVisitVerified:false|null};simulation:{eligible:boolean;approvalId:string|null;label:string|null}}};
type HomeworkReceipt={revision:string|null;status:"unavailable"|"available"|"acknowledged";acknowledgedAt:number|null};
type Tab="today"|"clients"|"earnings";
type EditorState={attendanceMode:"parent"|"trainer_led";parentConfirmed:boolean;safeArea:boolean;homework:string;scores:TrainingProgressScores;};
type Earning={session_id:string;booking_id:string;package_code:string;gross_earning:number|null;status:string;hold_reason:string|null;completed_at:number};
type Payout={period_code:string;earned_amount:number;earned_sessions:number;pending_sessions:number;held_sessions:number;status:string;execution_mode:string};
type EarningsData={providerId:string;earnings:Earning[];payouts:Payout[];livePayout:false;executionMode:string};
const statusLabel=(status:string)=>({scheduled:"Scheduled",accepted:"Accepted",on_the_way:"On the way",arrived:"Arrived",in_session:"In session",reschedule_requested:"Reschedule requested",completed:"Completed",no_show:"No-show",cancelled:"Cancelled"}[status]||status.replaceAll("_"," "));
const formatTime=(value:string)=>formatIndiaDateTimeMedium(value);
const money=(value:number)=>new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",minimumFractionDigits:2,maximumFractionDigits:2}).format(value||0);
const editorFrom=(session:TrainerSession):EditorState=>{const progress=session.progress||{};return{attendanceMode:String(session.attendance?.mode||"parent") as "parent"|"trainer_led",parentConfirmed:session.attendance?.parentOrCaretakerConfirmed===true,safeArea:session.attendance?.safeAreaConfirmed===true,homework:String(session.homework?.text||""),scores:trainingProgressFromRecord(progress)};};
async function providerEarnings(providerId:string){const response=await fetch(`/api/training-provider-earnings?providerId=${encodeURIComponent(providerId)}`,{cache:"no-store"}),body=await response.json() as {data?:EarningsData;error?:string};if(!response.ok||!body.data)throw new Error(body.error||"Unable to load Training earnings");return body.data;}
// A request id: the returned check stays true only while no newer request has started on the same counter.
const newestRequest=(counter:{current:number})=>{const request=++counter.current;return()=>request===counter.current;};
// The trainer's own display name from the public provider profile (the same safe fields customers already see); null keeps the provider id as the header fallback.
async function providerDisplayName(providerId:string){try{const response=await fetch(`/api/provider-public-profile?providerId=${encodeURIComponent(providerId)}`,{cache:"no-store"}),body=await response.json() as {data?:{displayName?:unknown}};const name=typeof body.data?.displayName==="string"?body.data.displayName.trim():"";return response.ok&&name?name:null;}catch{return null;}}

export default function TrainerPage(){return <Suspense fallback={null}><TrainerPageContent/></Suspense>;}

function TrainerPageContent(){
 const searchParams=useSearchParams(),pathname=usePathname(),inV2=pathname.startsWith("/v2/partner/trainer"),partnerHref=inV2?"/v2/partner":"/partner",trainingHref=inV2?"/v2/training":"/training",requestedBookingId=searchParams.get("bookingId")||"",requestedSessionId=searchParams.get("sessionId")||"",executionView=pathname.endsWith("/session")||searchParams.get("view")==="work",trainerHref=inV2?"/v2/partner/trainer":"/trainer";
 const[tab,setTab]=useState<Tab>("today"),[providerId,setProviderId]=useState(""),[sessions,setSessions]=useState<TrainerSession[]>([]),[selectedId,setSelectedId]=useState(""),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(""),[toast,setToast]=useState(""),[evidence,setEvidence]=useState<TrainingEvidenceAsset[]>([]),[earnings,setEarnings]=useState<EarningsData|null>(null),[attendanceMode,setAttendanceMode]=useState<"parent"|"trainer_led">("parent"),[parentConfirmed,setParentConfirmed]=useState(false),[safeArea,setSafeArea]=useState(false),[homework,setHomework]=useState(""),[scores,setScores]=useState<TrainingProgressScores>(()=>trainingProgressFromRecord());
 const[context,setContext]=useState<SessionContext|null>(null),[contextError,setContextError]=useState(""),[clock,setClock]=useState(()=>Date.now());
 const[evidenceSessionId,setEvidenceSessionId]=useState(""),[evidenceLoading,setEvidenceLoading]=useState(false);
 const[evidenceError,setEvidenceError]=useState(""),[trainerName,setTrainerName]=useState("");
 const[earningsLoading,setEarningsLoading]=useState(false),[earningsError,setEarningsError]=useState("");
 const earningsRequest=useRef(0),evidenceRequest=useRef(0),selectedRef=useRef("");
 useEffect(()=>{selectedRef.current=selectedId;},[selectedId]);
 const selected=useMemo(()=>sessions.find(item=>item.id===selectedId&&(!executionView||item.id===requestedSessionId&&(!requestedBookingId||item.booking_id===requestedBookingId)))||null,[sessions,selectedId,executionView,requestedSessionId,requestedBookingId]);
 useEffect(()=>{let active=true;const load=async()=>{if(!selectedId)return;try{const response=await fetch(`/api/training-session-context?sessionId=${encodeURIComponent(selectedId)}`,{cache:"no-store",credentials:"include"});const body=await response.json() as {data?:SessionContext;error?:string};if(!response.ok||!body.data)throw new Error(body.error||"Unable to load session visit context");if(active)setContext(body.data);}catch(problem){if(active){setContext(null);setContextError(problem instanceof Error?problem.message:"Unable to load visit context");}}};queueMicrotask(()=>{if(!active)return;setContext(null);setContextError("");void load();});const timer=selectedId?window.setInterval(()=>{setClock(Date.now());void load();},30_000):undefined;return()=>{active=false;if(timer!==undefined)window.clearInterval(timer);};},[selectedId,selected?.status,selected?.ownerHandover]);
 const currentContext=context?.sessionId===selected?.id?context:null;
 const homeworkReceipt=(selected as (TrainerSession&{homeworkReceipt?:HomeworkReceipt})|null)?.homeworkReceipt;
 const programmes=useMemo(()=>{const map=new Map<string,TrainerSession>();for(const session of sessions)if(!map.has(session.programme_id))map.set(session.programme_id,session);return[...map.values()];},[sessions]);
 const earnedAmount=useMemo(()=>earnings?.earnings.filter(item=>item.status==="earned").reduce((sum,item)=>sum+Number(item.gross_earning||0),0)||0,[earnings]);
 const notify=(message:string)=>{setToast(message);window.setTimeout(()=>setToast(""),2600);};
 const applyEditor=(editor:EditorState)=>{setAttendanceMode(editor.attendanceMode);setParentConfirmed(editor.parentConfirmed);setSafeArea(editor.safeArea);setHomework(editor.homework);setScores(editor.scores);};
 // Only the newest evidence read may write, so a slow response for an earlier selection (or an older read of this one) cannot replace the photos now shown.
 async function showEvidence(sessionId:string){const current=newestRequest(evidenceRequest);setEvidence([]);setEvidenceSessionId("");setEvidenceLoading(true);setEvidenceError("");try{const result=await loadTrainingEvidence(sessionId);if(current()&&selectedRef.current===sessionId){setEvidence(result.assets);setEvidenceSessionId(sessionId);}}catch(problem){if(current()&&selectedRef.current===sessionId){setEvidence([]);setEvidenceError(problem instanceof Error?problem.message:"Unable to load session photos. Please retry.");}}finally{if(current()&&selectedRef.current===sessionId)setEvidenceLoading(false);}}
 async function selectSession(session:TrainerSession){selectedRef.current=session.id;setSelectedId(session.id);applyEditor(editorFrom(session));await showEvidence(session.id);}
 // The selection is read after the load, so a session picked while Refresh was in flight is kept rather than replaced by the one selected when it started.
 async function refresh(id=providerId,preferredSessionId?:string){if(!id)return;const rows=await loadTrainerSessions(id);setSessions(rows);const wanted=preferredSessionId??selectedRef.current,next=executionView?rows.find(row=>row.id===requestedSessionId&&(!requestedBookingId||row.booking_id===requestedBookingId))||null:rows.find(row=>row.id===wanted)||rows[0]||null;if(next){selectedRef.current=next.id;setSelectedId(next.id);applyEditor(editorFrom(next));await showEvidence(next.id);}else{selectedRef.current="";evidenceRequest.current++;setSelectedId("");setEvidence([]);setEvidenceSessionId("");setEvidenceLoading(false);}if(!executionView&&tab==="earnings")await loadEarnings(id);}
 async function loadEarnings(id=providerId){if(!id)return;const request=++earningsRequest.current;setEarningsLoading(true);setEarningsError("");setEarnings(null);try{const data=await providerEarnings(id);if(request===earningsRequest.current)setEarnings(data);}catch(problem){if(request===earningsRequest.current)setEarningsError(problem instanceof Error?problem.message:"Unable to load Training earnings");}finally{if(request===earningsRequest.current)setEarningsLoading(false);}}
 async function openTab(next:Tab){setTab(next);setError("");if(next==="earnings")await loadEarnings();}
 /*
  * The workspace opens as soon as the sessions are listed. It used to wait for the selected session's photos
  * too, three sequential requests behind "Loading trainer workspace…", which outlasted the staging E2E run's
  * waits (36243387701). Photos and the display name now follow; `active` drops a superseded run's results.
  */
 useEffect(()=>{let active=true;void(async()=>{try{const identity=await currentProviderIdentity();if(identity.subjectType!=="provider")throw new Error("A provider identity session is required for the trainer workspace");const rows=await loadTrainerSessions(identity.subjectId);if(!active)return;setProviderId(identity.subjectId);setSessions(rows);const requested=rows.find(item=>item.id===requestedSessionId&&(!requestedBookingId||item.booking_id===requestedBookingId)),first=executionView?requested||null:requested||rows.find(item=>item.booking_id===requestedBookingId)||rows[0]||null;if(first){const editor=editorFrom(first);selectedRef.current=first.id;setSelectedId(first.id);setAttendanceMode(editor.attendanceMode);setParentConfirmed(editor.parentConfirmed);setSafeArea(editor.safeArea);setHomework(editor.homework);setScores(editor.scores);}setLoading(false);void providerDisplayName(identity.subjectId).then(name=>{if(active)setTrainerName(name||"");});if(first)await showEvidence(first.id);}catch(problem){if(active){setError(problem instanceof Error?problem.message:"Unable to authenticate trainer");setLoading(false);}}})();return()=>{active=false;};},[requestedBookingId,requestedSessionId,executionView]);
 async function act(action:string,extra:Record<string,unknown>={}){if(!selected||selectedRef.current!==selected.id||(["save_report","complete"].includes(action)&&!evidenceSettled))return;setBusy(true);setError("");try{await trainingSessionAction({sessionId:selected.id,action,...extra} as Parameters<typeof trainingSessionAction>[0]);if(action==="owner_handover")setSessions(await loadTrainerSessions(providerId));else await refresh(providerId,selected.id);notify(`Session ${action.replaceAll("_"," ")} recorded`);}catch(problem){setError(problem instanceof Error?problem.message:"Training session update failed");}finally{setBusy(false);}}
 const evidenceSettled=Boolean(selected&&evidenceSessionId===selected.id&&!evidenceLoading&&!evidenceError);
 const proofReady=(evidenceSettled?evidence:[]).filter(item=>item.proofReady),hasBothPhotos=["before_service","after_service"].every(purpose=>proofReady.some(item=>item.purpose===purpose));
 const report={attendance:{mode:attendanceMode,parentOrCaretakerConfirmed:attendanceMode==="parent"?parentConfirmed:false,safeAreaConfirmed:safeArea},homework,progress:scores,evidenceRefs:proofReady.map(item=>item.ref)};
 const attendanceReady=safeArea&&(attendanceMode!=="parent"||parentConfirmed);
 const savedAttendanceReady=trainingAttendanceReady(selected?.attendance);
 const beforePhotoCaptured=evidenceSettled&&trainingBeforeCaptured(evidence);
 const attendanceControls=<><label><input type="radio" checked={attendanceMode==="parent"} onChange={()=>setAttendanceMode("parent")}/> Parent/caretaker present</label><label><input type="radio" checked={attendanceMode==="trainer_led"} onChange={()=>setAttendanceMode("trainer_led")}/> Trainer-led permitted programme</label>{attendanceMode==="parent"&&<label><input type="checkbox" checked={parentConfirmed} onChange={event=>setParentConfirmed(event.target.checked)}/> Parent/caretaker attendance confirmed</label>}<label><input type="checkbox" checked={safeArea} onChange={event=>setSafeArea(event.target.checked)}/> Training area is safe</label></>;
 async function startSession(){if(!selected||!savedAttendanceReady||!beforePhotoCaptured)return;setBusy(true);setError("");try{await trainingSessionAction({sessionId:selected.id,action:"start"});await refresh(providerId,selected.id);notify("Session start recorded");}catch(problem){setError(problem instanceof Error?problem.message:"Training session update failed");}finally{setBusy(false);}}
 async function refreshEvidence(){if(!selected||busy)return;setBusy(true);try{await showEvidence(selected.id);}finally{setBusy(false);}}
 async function addEvidence(file:File,purpose:TrainingEvidencePurpose){if(!selected||busy||selectedRef.current!==selected.id)return;if(purpose==="before_service"&&(selected.status!=="arrived"||!savedAttendanceReady)||purpose==="after_service"&&(selected.status!=="in_session"||!selected.ownerHandover?.completedAt))return;if(purpose==="training_video"&&!trainingVideoValidation(file)){setError("Choose an MP4 or WebM training video no larger than 10 MB.");return;}setBusy(true);setError("");const current=newestRequest(evidenceRequest);try{const uploaded=await prepareTrainingEvidence({sessionId:selected.id,file,purpose});const result=await loadTrainingEvidence(selected.id);if(current()){setEvidence(result.assets);setEvidenceSessionId(selected.id);setEvidenceError("");}notify(uploaded.alreadyUploaded?"This evidence is already registered. Its current approval status is shown below.":uploaded.objectStored?"Evidence uploaded. Waiting for scan and independent approval.":"Evidence bytes received in sandbox; private storage is not connected. Completion still requires approved proof.");}catch(problem){setError(problem instanceof Error?problem.message:"Unable to upload Training evidence");try{const result=await loadTrainingEvidence(selected.id);if(current())setEvidence(result.assets);}catch{if(current())setEvidenceError("Unable to reload photos. Retry the approval refresh.");}}finally{setBusy(false);}}
 const visitControls=selected&&<>{currentContext?.arrival.evidence?.simulated&&<p role="status">Sandbox arrival simulation — not a physical visit.</p>}{currentContext?.navigation.available&&currentContext.navigation.mapsUrl&&<p><a href={currentContext.navigation.mapsUrl} target="_blank" rel="noopener noreferrer">Navigate to customer doorstep</a></p>}{contextError&&<p role="alert">{contextError}</p>}{currentContext&&!currentContext.navigation.available&&currentContext.navigation.reason&&<p>{currentContext.navigation.reason==="address_window_closed"?"Customer navigation becomes available within the approved address-access window before the session.":"Customer navigation is unavailable. Contact Operations if you need help reaching this session."}</p>}<div className={styles.actions}>{selected.providerModel!=="full_time"&&<button disabled={busy||selected.status!=="scheduled"} onClick={()=>void act("accept")}>Accept</button>}<button disabled={busy||!(selected.status==="accepted"||selected.providerModel==="full_time"&&selected.status==="scheduled")} onClick={()=>void act("on_the_way")}>On the way</button><button disabled={busy||selected.status!=="on_the_way"} onClick={()=>void act("arrive")}>Confirm arrival with device GPS</button></div>{selected.status==="on_the_way"&&currentContext?.arrival.simulation.eligible&&currentContext.arrival.simulation.approvalId&&<section className={styles.precheck}><p>{currentContext.arrival.simulation.label}. This records a test simulation, not a physical visit.</p><button disabled={busy} onClick={()=>{const reason=window.prompt("Explain this approved sandbox arrival simulation (at least 8 characters)")?.trim();if(reason&&reason.length>=8)void act("arrive",{simulatedArrival:{approvalId:currentContext.arrival.simulation.approvalId,reason}});}}>Simulate approved sandbox arrival</button></section>}{["scheduled","accepted","on_the_way","arrived"].includes(selected.status)&&<section className={styles.precheck}><span>RECOVERY</span><p>Reschedule requests and no-show records open an auditable recovery case; they do not silently consume a paid session.</p><button disabled={busy} onClick={()=>{const reason=window.prompt("Why must this session be rescheduled?")||"";if(reason)void act("request_reschedule",{reason});}}>Request reschedule</button><button disabled={busy} onClick={()=>{const reason=window.prompt("Record the no-show reason")||"";if(reason)void act("no_show",{reason});}}>Record no-show</button></section>}</>;
 const appointmentControls=selected&&<>{(selected as TrainerSession&{schedulingMode?:string}).schedulingMode==="rolling_v1"&&<TrainerRollingSchedule key={selected.id} bookingId={selected.booking_id} sessionId={selected.id} providerId={providerId} onChanged={()=>refresh(providerId,selected.id)}/>}</>;
 if(loading)return <main className={styles.shell}><section className={styles.main}><h1>Loading trainer workspace…</h1></section></main>;
 if(!providerId)return <main className={styles.shell}><section className={styles.main}><h1>Trainer sign-in required</h1><p>{error||"Verify the trainer identity with the PawSpace provider OTP session before opening assigned sessions."}</p><Link href={partnerHref}>Return to Partner</Link></section></main>;
 const nowLabel=new Intl.DateTimeFormat("en-IN",{weekday:"long",day:"numeric",month:"long"}).format(new Date());
 return <main className={`${styles.shell} ${executionView?styles.workShell:""}`}>
  {!executionView&&<aside><div className={styles.brand}><span>paw●space</span><small>TRAINER PARTNER</small></div><div className={styles.trainer}><span>TR</span><div><strong>{trainerName||providerId}</strong><small>Authenticated provider session</small></div></div><nav><button className={tab==="today"?styles.active:""} onClick={()=>void openTab("today")}>▦ Sessions</button><button className={tab==="clients"?styles.active:""} onClick={()=>void openTab("clients")}>🐾 Programmes</button><button className={tab==="earnings"?styles.active:""} onClick={()=>void openTab("earnings")}>₹ Earnings</button></nav><div className={styles.links}><Link href={partnerHref}>Partner home</Link><Link href={trainingHref}>Customer training</Link></div></aside>}
  <section className={`${styles.main} ${executionView?styles.workMain:""}`}><header><div>{executionView&&<Link href={trainerHref}>Back to your jobs</Link>}<p>{nowLabel}</p><h1>{executionView?"Training session work":tab==="today"?"Your training sessions":tab==="clients"?"Dogs & programmes":"Training earnings readiness"}</h1></div>{!executionView&&<span><i></i>{sessions.length} assigned session{sessions.length===1?"":"s"}</span>}</header>
   {error&&<section className={styles.success} role="alert"><p>{error}</p></section>}
   {!executionView&&tab==="today"&&<TrainingBroadcastInbox providerId={providerId} onAward={sessionId=>refresh(providerId,sessionId)}/>}
   {(executionView||tab==="today")&&<section className={executionView?styles.workLayout:styles.layout}>{!executionView&&<div className={styles.schedule}><div className={styles.heading}><div><span>YOUR SESSIONS</span><h2>{sessions.length?sessions.length:"No"} assigned sessions</h2></div><button disabled={busy} onClick={()=>void refresh()}>Refresh</button></div>{sessions.length===0&&<article className={styles.meetRequest}><b>No Training sessions are currently assigned to this authenticated trainer.</b><small>Assignments appear here only after a customer programme is materialized and this provider owns the session.</small></article>}{sessions.map(session=><div key={session.id} className={styles.jobCard}><button aria-expanded={selected?.id===session.id} aria-controls={`job-detail-${session.id}`} disabled={busy} className={selected?.id===session.id?styles.selected:""} onClick={()=>void selectSession(session)}><span>{formatTime(session.scheduled_start)}<small>{statusLabel(session.status)}</small></span><div><strong>{session.plan_name}</strong><small>{session.customer_name} · Session {session.sequence_no} of {session.total_sessions}</small></div><b>{session.completed_sessions}/{session.total_sessions} complete</b></button>{selected?.id===session.id&&<div id={`job-detail-${session.id}`} className={styles.inlineDetails}><p>Booking {session.booking_id} · Session {session.sequence_no} of {session.total_sessions}</p><p>{session.customer_name} · {session.plan_name}</p>{visitControls}<Link className={styles.workLink} href={`${trainerHref}/session?bookingId=${encodeURIComponent(session.booking_id)}&sessionId=${encodeURIComponent(session.id)}`}>Open session work</Link>{appointmentControls}</div>}</div>)}</div>}
    {executionView&&!selected&&<section role="alert"><h2>Session unavailable</h2><p>This requested session is not in your assigned jobs. Return to your jobs and choose an assigned session.</p></section>}{executionView&&selected&&<article className={styles.session}><div className={styles.sessionHead}><div><span>{selected.id} · Booking {selected.booking_id}</span><h2>{selected.plan_name}</h2><p>{selected.customer_name} · Session {selected.sequence_no} of {selected.total_sessions}</p></div><b>{statusLabel(selected.status)}</b></div>
     {!["arrived","in_session","completed"].includes(selected.status)&&<p>Confirm arrival from your jobs list before starting session work.</p>}
     {selected.status==="arrived"&&<section className={styles.precheck}><span>SESSION PRE-CHECK</span><p>Save attendance and safe-area confirmation, then capture the before photo before starting.</p>{attendanceControls}<button disabled={busy||!evidenceSettled||!attendanceReady} onClick={()=>void act("save_report",{report:{attendance:report.attendance}})}>Save attendance &amp; safety</button><button disabled={busy||!savedAttendanceReady||!beforePhotoCaptured} onClick={()=>void startSession()}>Start session</button></section>}
     {selected.status==="arrived"&&<TrainingEvidenceControls purpose="before_service" canUpload={evidenceSettled&&savedAttendanceReady} assets={evidenceSettled?evidence:[]} busy={busy||evidenceLoading} error={evidenceError} onUpload={(file,purpose)=>void addEvidence(file,purpose)} onRefresh={()=>void refreshEvidence()}/>}
     {selected.status==="in_session"&&<><TrainingVideoControls assets={evidenceSettled?evidence:[]} busy={busy||evidenceLoading} onUpload={(file,purpose)=>void addEvidence(file,purpose)}/><TrainingOwnerHandover key={`${selected.id}:${selected.ownerHandover?.completedAt??"unsaved"}`} record={selected.ownerHandover} busy={busy} reminderDue={Boolean(currentContext?.handover.reminderDue||trainingHandoverReminder(currentContext?.handover.remindAt,clock))} onRecord={minutes=>void act("owner_handover",{ownerHandoverCompleted:true,...(minutes===undefined?{}:{ownerHandoverMinutes:minutes})})}/><TrainingEvidenceControls purpose="after_service" canUpload={evidenceSettled&&Boolean(selected.ownerHandover?.completedAt)} assets={evidenceSettled?evidence:[]} busy={busy||evidenceLoading} error={evidenceError} onUpload={(file,purpose)=>void addEvidence(file,purpose)} onRefresh={()=>void refreshEvidence()}/><p>Before photo: {proofReady.some(asset=>asset.purpose==="before_service")?"Approved":beforePhotoCaptured?"Awaiting independent approval":"Needs Operations review"}</p><section className={styles.goals}><span>SESSION PLAN · SERVER-OWNED</span><p>Goals snapshot: {selected.requirements.length?selected.requirements.join(" · "):"No programme requirements were recorded"}</p><p>Completion requires attendance, homework, 1–10 progress scores and clean secure media linked to this exact session.</p></section><section className={styles.scoreGrid}>{Object.entries(scores).map(([key,value])=><label key={key}><span>{key==="parent"?"Parent practice":key[0].toUpperCase()+key.slice(1)} <b>{value===null?"Unassessed":`${value}/10`}</b></span><select aria-label={`${key==="parent"?"Parent practice":key[0].toUpperCase()+key.slice(1)} score`} value={value??""} disabled={busy} onChange={event=>setScores(current=>({...current,[key]:event.target.value===""?null:Number(event.target.value)}))}><option value="">Choose an assessment</option>{value!==null&&(value<1||value>10)&&<option value={value}>{value} · needs correction</option>}{Array.from({length:10},(_,index)=><option key={index+1} value={index+1}>{index+1}/10</option>)}</select></label>)}</section><label className={styles.homework}><span>Homework for pet parent</span><textarea value={homework} onChange={event=>setHomework(event.target.value)}/></label><p role="status">{trainingHomeworkStatus(homeworkReceipt?.status)}</p><button disabled={busy} onClick={()=>void refresh()}>Refresh parent homework acknowledgement</button><section className={styles.precheck}><span>ATTENDANCE & SAFETY</span><p>Confirm who is present and that the training area is safe. This is saved with the report and is required to complete the session.</p>{attendanceControls}</section><div className={styles.actions}><button disabled={busy||!evidenceSettled} onClick={()=>void act("save_report",{report})}>Save report</button><button className={styles.complete} disabled={busy||!evidenceSettled||Boolean(evidenceError)||homework.trim().length<10||!hasBothPhotos||!selected.ownerHandover||!attendanceReady||!trainingProgressReady(scores)} onClick={()=>void act("complete",{report})}>Complete & consume one session</button></div></>}

     {selected.status==="completed"&&<section className={styles.success}><i>✓</i><h2>Session completed</h2><p>Exactly one session consumption is recorded. Attendance, scores, homework and secure evidence remain attached to this session.</p></section>}
     {selected.status==="reschedule_requested"&&<section className={styles.success}><h2>Reschedule awaiting staff action</h2><p>The trainer cannot rewrite the canonical calendar. Team Operations must approve a new future slot after conflict checks.</p></section>}
     {selected.status==="no_show"&&<section className={styles.success}><h2>No-show recovery case open</h2><p>Session consumption is intentionally pending policy; it is not automatically charged as completed.</p></section>}
