.sessionHead{display:flex;justify-content:space-between}.sessionHead h2{margin:4px 0 1px;font-size:24px}.sessionHead p{margin:0;color:var(--ui-muted);font-size:8px}.sessionHead>b{padding:5px 8px;align-self:flex-start;border-radius:99px;background:var(--ui-canvas);color:var(--ui-ink);font-size:7px}.actions{margin:12px 0;display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.actions button{padding:8px;border:1px solid var(--ui-line);border-radius:calc(8px * var(--paw-radius-scale));background:var(--ui-surface);color:var(--ui-ink);font-size:8px;font-weight:850}.precheck,.goals,.media,.homework{margin-top:10px;padding:11px;display:grid;gap:8px;border:1px solid var(--ui-canvas);border-radius:calc(10px * var(--paw-radius-scale));background:var(--ui-surface)}.precheck label,.goals label{font-size:8px}.precheck>button,.complete{padding:10px;border:0;border-radius:calc(8px * var(--paw-radius-scale));background:var(--ui-gold-primary);color:var(--ui-on-gold);font-size:8px;font-weight:900}.scoreGrid{margin-top:10px;display:grid;grid-template-columns:1fr 1fr;gap:7px}.scoreGrid label{padding:9px;display:grid;gap:5px;border:1px solid var(--ui-canvas);border-radius:calc(9px * var(--paw-radius-scale));background:var(--ui-surface)}.scoreGrid label span{display:flex;justify-content:space-between;color:var(--ui-muted);font-size:8px}.scoreGrid select{min-height:36px;padding:6px;border:1px solid var(--ui-line);border-radius:6px;background:var(--ui-surface);color:var(--ui-ink);font:inherit}.media{grid-template-columns:1fr auto;align-items:center}.media h3{margin:3px 0;font-size:11px}.media p{margin:0;color:var(--ui-muted);font-size:7px}.media button{padding:8px;border:1px solid var(--ui-line);border-radius:calc(8px * var(--paw-radius-scale));background:var(--ui-surface);color:var(--ui-ink);font-size:8px;font-weight:850}.homework span{font-size:8px;font-weight:850}.homework textarea{min-height:58px;padding:8px;border:1px solid var(--ui-line);border-radius:7px;font:inherit;font-size:8px;resize:vertical}.complete{width:100%;margin-top:10px}.success{padding:25px;text-align:center}.success>i{width:46px;height:46px;margin:auto;display:grid;place-items:center;border-radius:50%;background:#e5f6ed;color:#13734f;font-size:20px;font-style:normal}.success h2{margin:10px 0 4px}.success p{color:#756b7c;font-size:8px}.success div{display:flex;justify-content:center;gap:7px}.success button{padding:8px;border:1px solid #dcd3e2;border-radius:calc(8px * var(--paw-radius-scale));background:var(--ui-surface);color:#176f55;font-size:8px;font-weight:850}.success button:first-child{border:0;background:#f1a11d;color:#321800}
.clientGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.clientGrid article>span{width:43px;height:43px;display:grid;place-items:center;border-radius:calc(11px * var(--paw-radius-scale));background:var(--ui-canvas);color:var(--ui-ink);font-size:9px;font-weight:900}.clientGrid h2{margin:11px 0 2px}.clientGrid p{margin:0;color:var(--ui-muted);font-size:8px}.clientGrid article div{margin:14px 0;padding:10px;display:flex;flex-direction:column;border-radius:calc(9px * var(--paw-radius-scale));background:var(--ui-canvas)}.clientGrid div strong{font-size:9px}.clientGrid div small{color:var(--ui-muted);font-size:7px}.clientGrid button{width:100%;padding:8px;border:1px solid var(--ui-line);border-radius:calc(8px * var(--paw-radius-scale));background:var(--ui-surface);color:var(--ui-ink);font-size:8px;font-weight:850}.earnings{display:grid;gap:12px}.hero{color:white;background:linear-gradient(135deg,var(--ui-brand-deep),var(--ui-brand-deep))}.hero>strong{margin:5px 0;display:block;font-size:38px}.hero p{color:var(--ui-soft-ink);font-size:8px}.hero div{display:flex;gap:8px}.hero b{padding:6px 8px;border-radius:99px;background:color-mix(in srgb, var(--ui-surface) 10%, transparent);color:var(--ui-on-primary);font-size:7px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stats article span{color:var(--ui-muted);font-size:8px}.stats article strong{margin:4px 0;display:block;font-size:19px}.stats article small{color:var(--ui-muted);font-size:7px}.statement h2{margin-top:0}.statement div{padding:10px 0;display:flex;justify-content:space-between;border-top:1px solid var(--ui-canvas);font-size:9px}.statement div:nth-last-of-type(1){font-weight:900}.statement button{margin-top:10px;padding:8px;border:1px solid var(--ui-line);border-radius:calc(8px * var(--paw-radius-scale));background:var(--ui-surface);color:var(--ui-ink);font-size:8px;font-weight:850}.toast{position:fixed;right:20px;bottom:20px;padding:12px 16px;border-radius:calc(10px * var(--paw-radius-scale));background:var(--ui-brand-deep);color:white;font-size:9px;font-weight:900}
@media(max-width:760px){.shell{display:block}.shell>aside{position:relative;height:auto}.shell>aside nav{grid-template-columns:repeat(3,1fr)}.links{display:none}.main{padding:18px 12px}.layout{grid-template-columns:1fr}.session{margin-top:12px}.clientGrid,.stats{grid-template-columns:1fr}.toast{right:12px;left:12px;text-align:center}}

/* Keep the session columns within the available workspace width. */
.actions button{min-height:44px}
@media(max-width:1100px){.layout{grid-template-columns:minmax(0,1fr)}.schedule,.session{min-width:0}}

/* Selected job details stay with the card; execution has its own focused page. */
.layout,.workLayout{display:grid;grid-template-columns:minmax(0,1fr);gap:16px}
.jobCard+ .jobCard{margin-top:12px}
.jobCard>button{width:100%;min-height:56px;padding:12px;display:grid;grid-template-columns:minmax(120px,.7fr) minmax(0,1fr) auto;gap:12px;align-items:center;border:1px solid var(--ui-line);border-radius:10px;background:var(--ui-surface);color:var(--ui-ink);text-align:left;cursor:pointer}
.jobCard>button[aria-expanded="true"]{border-color:var(--ui-brand-soft);background:var(--ui-canvas)}
.jobCard>button>span,.jobCard>button>div{display:grid;gap:4px;min-width:0}.jobCard>button small{color:var(--ui-muted)}
.inlineDetails{padding:16px;border:1px solid var(--ui-line);border-top:0;border-radius:0 0 10px 10px}.inlineDetails p{font-size:14px;line-height:1.5}
.workLink{display:inline-block;margin:12px 0;padding:12px 16px;border-radius:8px;background:var(--ui-brand-deep);color:white;text-decoration:none;font-weight:700}
.workShell{display:block}.workMain{max-width:860px;margin:0 auto}.workMain>header h1{font-size:28px}.workMain>header a{display:inline-block;margin-bottom:12px;font-size:16px}.workLayout .session{margin-top:0}
.workMain .precheck,.workMain .goals,.workMain .homework{font-size:14px;line-height:1.5}.workMain .precheck label,.workMain .goals label,.workMain .homework textarea,.workMain .homework span,.workMain .scoreGrid label span{font-size:14px}
@media(max-width:560px){.jobCard>button{grid-template-columns:minmax(0,1fr)}.inlineDetails{padding:12px}.workMain{padding:18px 12px}}

.jobCard>button>span,.jobCard>button strong{font-size:16px}.jobCard>button small,.jobCard>button b{font-size:13px}.workMain .precheck>button,.workMain .actions button,.inlineDetails .actions button,.workMain .scoreGrid select{min-height:44px;font-size:14px}
